package vn.uteb;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.web.multipart.MultipartFile;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.net.*;import java.net.http.*;import java.time.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;
import static vn.uteb.ShopService.*;import static vn.uteb.Domain.*;
@Service @Transactional
public class MediaService {
 final ShopService shop;final ObjectMapper json;final String cloud,key,secret;
 MediaService(ShopService shop,ObjectMapper json,@Value("${uteb.cloudinary.cloud}")String cloud,@Value("${uteb.cloudinary.key}")String key,@Value("${uteb.cloudinary.secret}")String secret){this.shop=shop;this.json=json;this.cloud=cloud;this.key=key;this.secret=secret;}
 MediaRecord upload(MultipartFile f)throws Exception{Account a=shop.me();require(f.getSize()>0&&f.getSize()<=10*1024*1024,"Tệp cần nhỏ hơn 10MB.");byte[] bytes=f.getBytes();boolean jpg=bytes.length>3&&(bytes[0]&255)==255&&(bytes[1]&255)==216;boolean png=bytes.length>8&&bytes[0]==(byte)137&&bytes[1]==80&&bytes[2]==78&&bytes[3]==71;boolean webp=bytes.length>12&&new String(bytes,0,4,StandardCharsets.US_ASCII).equals("RIFF")&&new String(bytes,8,4,StandardCharsets.US_ASCII).equals("WEBP");boolean mp4=bytes.length>12&&new String(bytes,4,4,StandardCharsets.US_ASCII).equals("ftyp");require(jpg||png||webp||mp4,"Chỉ nhận JPEG, PNG, WebP hoặc MP4.");require(!cloud.isEmpty()&&!key.isEmpty()&&!secret.isEmpty(),"Cloudinary chưa cấu hình. Điền biến môi trường rồi khởi động lại.");String kind=mp4?"video":"image",timestamp=Long.toString(Instant.now().getEpochSecond()),folder="uteb/"+a.id;String raw="folder="+folder+"&timestamp="+timestamp+secret,signature=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-1").digest(raw.getBytes(StandardCharsets.UTF_8))),boundary="UTEB"+UUID.randomUUID();ByteArrayOutputStream out=new ByteArrayOutputStream();for(var e:Map.of("api_key",key,"timestamp",timestamp,"signature",signature,"folder",folder).entrySet())out.write(("--"+boundary+"\r\nContent-Disposition: form-data; name=\""+e.getKey()+"\"\r\n\r\n"+e.getValue()+"\r\n").getBytes(StandardCharsets.UTF_8));out.write(("--"+boundary+"\r\nContent-Disposition: form-data; name=\"file\"; filename=\"upload."+(mp4?"mp4":png?"png":webp?"webp":"jpg")+"\"\r\nContent-Type: "+(mp4?"video/mp4":png?"image/png":webp?"image/webp":"image/jpeg")+"\r\n\r\n").getBytes(StandardCharsets.UTF_8));out.write(bytes);out.write(("\r\n--"+boundary+"--\r\n").getBytes(StandardCharsets.UTF_8));var req=HttpRequest.newBuilder(URI.create("https://api.cloudinary.com/v1_1/"+cloud+"/"+kind+"/upload")).timeout(Duration.ofSeconds(30)).header("Content-Type","multipart/form-data; boundary="+boundary).POST(HttpRequest.BodyPublishers.ofByteArray(out.toByteArray())).build();var res=HttpClient.newHttpClient().send(req,HttpResponse.BodyHandlers.ofString());require(res.statusCode()==200,"Cloudinary từ chối tệp; kiểm tra cấu hình.");Map<?,?>body=json.readValue(res.body(),Map.class);MediaRecord m=new MediaRecord();m.userId=a.id;m.url=body.get("secure_url").toString();m.publicId=body.get("public_id").toString();m.kind=kind;return shop.save(m);}
}
